import React, { Component } from 'react';
import { Card, Table, Icon, Button, Spin, Alert, Input, Dropdown, Menu, Modal, message, Tag } from 'antd';
import { getInstance } from 'd2/lib/d2';
import PropTypes from 'prop-types';

const { Search } = Input;

class DataElementsList extends Component {
    constructor(props) {
        super(props);
        this.state = {
            dataElements: [], // All data elements
            loading: false,
            error: null,
            searchValue: '',
            filteredDataElements: [],
            deletingDataElementId: null, // Track which data element is being deleted
            selectedDataElementIds: [], // Track selected data elements for bulk operations
            isDeleting: false, // Track bulk delete operation
            refreshing: false // Track refresh operation
        };
        this._isMounted = false;
    }

    componentDidMount() {
        this._isMounted = true;
        this.fetchDataElements();
    }

    componentWillUnmount() {
        this._isMounted = false;
    }

    fetchDataElements = async () => {
        if (!this._isMounted) return;

        this.setState({ loading: true, error: null });

        try {
            const d2 = await getInstance();
            const api = d2.Api.getApi();
            const data = await api.get('dataElements', {
                filter: 'name:ne:default',
                fields: 'displayName,shortName,id,lastUpdated,created,displayDescription,code,sharing,access,href,level,displayName,domainType,valueType,categoryCombo[displayName],lastUpdated',
                order: 'displayName:ASC',
                paging: false
            });
            
            if (this._isMounted) {
                this.setState({
                    dataElements: data.dataElements || [],
                    filteredDataElements: data.dataElements || [],
                    loading: false
                });
            }
        } catch (error) {
            console.error('Error fetching data elements:', error);
            if (this._isMounted) {
                this.setState({
                    error: 'Failed to fetch data elements. Please try again.',
                    loading: false
                });
            }
        }
    };

    handleDataElementClick = (dataElement) => {
        const redirectUrl = `/sims-web-maintenance/#/edit/dataElementSection/dataElement/${dataElement.id}`;
        window.location.href = redirectUrl;
    };

    handleDataElementView = (dataElement) => {
        // Navigate to data element details/view page
        const redirectUrl = `/sims-web-maintenance/#/view/dataElementSection/dataElement/${dataElement.id}`;
        window.location.href = redirectUrl;
    };

    handleDataElementDelete = (dataElement) => {
        Modal.confirm({
            title: 'Delete Data Element',
            content: (
                <div>
                    <p>Are you sure you want to delete the data element <strong>"{dataElement.displayName}"</strong>?</p>
                    <p style={{ color: '#ff4d4f', marginBottom: 0 }}>This action cannot be undone.</p>
                </div>
            ),
            okText: 'Delete',
            okType: 'danger',
            cancelText: 'Cancel',
            width: 450,
            onOk: () => {
                return this.deleteDataElement(dataElement.id);
            },
        });
    };

    deleteDataElement = async (dataElementId) => {
        this.setState({ deletingDataElementId: dataElementId });

        try {
            const d2 = await getInstance();
            const api = d2.Api.getApi();
            await api.delete(`dataElements/${dataElementId}`);

            // Remove the deleted data element from state
            const updatedDataElements = this.state.dataElements.filter(dataElement => dataElement.id !== dataElementId);
            const updatedFilteredDataElements = this.state.filteredDataElements.filter(dataElement => dataElement.id !== dataElementId);

            this.setState({
                dataElements: updatedDataElements,
                filteredDataElements: updatedFilteredDataElements,
                deletingDataElementId: null
            });

            message.success('Data element deleted successfully');
        } catch (error) {
            console.error('Error deleting data element:', error);
            this.setState({ deletingDataElementId: null });

            Modal.error({
                title: 'Delete Failed',
                content: `Failed to delete the data element: ${error.message}`,
            });
        }
    };

    handleCreateDataElement = () => {
        // Navigate to create new data element page
        const redirectUrl = `/sims-web-maintenance/#/edit/dataElementSection/dataElement/add`;
        window.location.href = redirectUrl;
    };

    handleDataElementExport = () => {
        // Navigate to metadata export page for data elements
        const redirectUrl = `/sims-web-import-export/#/export/metadata`;
        window.location.href = redirectUrl;
    };

    // Get more actions menu for data elements
    getDataElementActionsMenu = (dataElement) => {
        const { deletingDataElementId } = this.state;
        const isDeleting = deletingDataElementId === dataElement.id;

        return (
            <Menu>
                <Menu.Item key="edit" onClick={() => this.handleDataElementClick(dataElement)}>
                    <Icon type="edit" style={{ marginRight: 8 }} />
                    Edit Data Element
                </Menu.Item>
                <Menu.Item key="export" onClick={() => this.handleDataElementExport()}>
                    <Icon type="download" style={{ marginRight: 8 }} />
                    Export Data Elements
                </Menu.Item>
                <Menu.Divider />
                <Menu.Item
                    key="delete"
                    onClick={() => this.handleDataElementDelete(dataElement)}
                    disabled={isDeleting}
                    style={{ color: isDeleting ? '#ccc' : '#ff4d4f' }}
                >
                    <Icon type={isDeleting ? "loading" : "delete"} style={{ marginRight: '8px' }} />
                    {isDeleting ? 'Deleting...' : 'Delete Data Element'}
                </Menu.Item>
            </Menu>
        );
    };

    handleSearch = (value) => {
        const { dataElements } = this.state;

        if (!value.trim()) {
            this.setState({
                searchValue: value,
                filteredDataElements: dataElements
            });
            return;
        }

        const searchTerm = value.toLowerCase();
        const filteredDataElements = dataElements.filter(dataElement => {
            // Search in data element name, ID, code, short name, and description
            const dataElementMatches = dataElement.displayName.toLowerCase().includes(searchTerm) ||
                dataElement.id.toLowerCase().includes(searchTerm) ||
                (dataElement.code && dataElement.code.toLowerCase().includes(searchTerm)) ||
                (dataElement.shortName && dataElement.shortName.toLowerCase().includes(searchTerm)) ||
                (dataElement.displayDescription && dataElement.displayDescription.toLowerCase().includes(searchTerm));

            return dataElementMatches;
        });

        this.setState({
            searchValue: value,
            filteredDataElements: filteredDataElements
        });
    };

    formatDate = (dateString) => {
        if (!dateString) return 'N/A';
        const date = new Date(dateString);
        return date.toLocaleDateString() + ' ' + date.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
    };

    handleRefresh = async () => {
        this.setState({ refreshing: true });
        try {
            await this.fetchDataElements();
            this.setState({
                searchValue: '',
                selectedDataElementIds: [],
                refreshing: false
            });
            message.success('Data elements refreshed successfully');
        } catch (error) {
            console.error('Error refreshing data elements:', error);
            this.setState({ refreshing: false });
            message.error('Failed to refresh data elements');
        }
    };

    handleRowSelection = (selectedRowKeys) => {
        this.setState({ selectedDataElementIds: selectedRowKeys });
    };

    handleSelectAll = () => {
        const { dataElements, searchValue, filteredDataElements } = this.state;
        const dataSource = searchValue ? filteredDataElements : dataElements;
        const allIds = dataSource.map(dataElement => dataElement.id);
        this.setState({ selectedDataElementIds: allIds });
    };

    handleClearSelection = () => {
        this.setState({ selectedDataElementIds: [] });
    };

    handleBulkDelete = () => {
        const { selectedDataElementIds, dataElements } = this.state;
        const selectedDataElements = dataElements.filter(de => selectedDataElementIds.includes(de.id));

        Modal.confirm({
            title: 'Delete Selected Data Elements',
            content: (
                <div>
                    <p>Are you sure you want to delete <strong>{selectedDataElementIds.length} selected data element(s)</strong>?</p>
                    <div style={{ maxHeight: '150px', overflowY: 'auto', marginBottom: '15px' }}>
                        {selectedDataElements.map(dataElement => (
                            <div key={dataElement.id} style={{ padding: '2px 0', fontSize: '12px' }}>
                                • {dataElement.displayName}
                            </div>
                        ))}
                    </div>
                    <p style={{ color: '#ff4d4f', fontSize: '12px', marginBottom: 0 }}>
                        This action cannot be undone. Make sure you have backups if needed.
                    </p>
                </div>
            ),
            okText: `Delete ${selectedDataElementIds.length} Data Element(s)`,
            okType: 'danger',
            cancelText: 'Cancel',
            width: 600,
            onOk: () => {
                return this.deleteSelectedDataElements();
            },
        });
    };

    deleteSelectedDataElements = async () => {
        const { selectedDataElementIds } = this.state;
        this.setState({ isDeleting: true });

        const results = {
            successful: [],
            failed: []
        };

        try {
            const d2 = await getInstance();
            const api = d2.Api.getApi();

            for (const dataElementId of selectedDataElementIds) {
                const dataElement = this.state.dataElements.find(de => de.id === dataElementId);

                try {
                    await api.delete(`dataElements/${dataElementId}`);
                    results.successful.push(dataElementId);
                } catch (error) {
                    console.error(`Failed to delete data element ${dataElementId}:`, error);
                    results.failed.push({
                        id: dataElementId,
                        name: dataElement ? dataElement.displayName : dataElementId,
                        error: error.message || 'Unknown error'
                    });
                }
            }

            // Remove successfully deleted data elements from state
            const updatedDataElements = this.state.dataElements.filter(
                dataElement => !results.successful.includes(dataElement.id)
            );
            const updatedFilteredDataElements = this.state.filteredDataElements.filter(
                dataElement => !results.successful.includes(dataElement.id)
            );

            this.setState({
                dataElements: updatedDataElements,
                filteredDataElements: updatedFilteredDataElements,
                selectedDataElementIds: [],
                isDeleting: false
            });

            // Show appropriate messages
            if (results.successful.length > 0 && results.failed.length === 0) {
                message.success(`Successfully deleted ${results.successful.length} data element(s)`);
            } else if (results.successful.length > 0 && results.failed.length > 0) {
                Modal.info({
                    title: 'Partial Success',
                    content: (
                        <div>
                            <p><strong>Successfully deleted:</strong> {results.successful.length} data element(s)</p>
                            <p><strong>Failed to delete:</strong> {results.failed.length} data element(s)</p>
                            <div style={{ maxHeight: '150px', overflowY: 'auto', marginTop: '10px' }}>
                                {results.failed.map(failure => (
                                    <div key={failure.id} style={{ padding: '2px 0', fontSize: '12px', color: '#ff4d4f' }}>
                                        • {failure.name}: {failure.error}
                                    </div>
                                ))}
                            </div>
                        </div>
                    ),
                    width: 600,
                });
            } else if (results.failed.length > 0) {
                Modal.error({
                    title: 'Delete Failed',
                    content: (
                        <div>
                            <p>Failed to delete selected data elements:</p>
                            <div style={{ maxHeight: '150px', overflowY: 'auto', marginTop: '10px' }}>
                                {results.failed.map(failure => (
                                    <div key={failure.id} style={{ padding: '2px 0', fontSize: '12px' }}>
                                        • {failure.name}: {failure.error}
                                    </div>
                                ))}
                            </div>
                        </div>
                    ),
                    width: 600,
                });
            }
        } catch (error) {
            console.error('Error during bulk delete:', error);
            this.setState({ isDeleting: false });

            Modal.error({
                title: 'Bulk Delete Failed',
                content: `Unexpected error occurred: ${error.message}`,
            });
        }
    };

    render() {
        const { dataElements, loading, error, searchValue, filteredDataElements, selectedDataElementIds, isDeleting, refreshing } = this.state;

        const cardStyle = {
            margin: '20px auto',
            maxWidth: '1400px',
            borderRadius: '8px',
            boxShadow: '0 4px 12px rgba(0,0,0,0.1)'
        };

        const headerStyle = {
            padding: '24px',
            borderRadius: '8px 8px 0 0',
        };

        if (loading) {
            return (
                <Card style={cardStyle}>
                    <div style={{ textAlign: 'center', padding: '60px 0' }}>
                        <Spin size="large" />
                        <div style={{ marginTop: '16px', fontSize: '16px', color: '#666' }}>
                            Loading data elements...
                        </div>
                    </div>
                </Card>
            );
        }

        if (error) {
            return (
                <Card style={cardStyle}>
                    <div style={{ padding: '40px' }}>
                        <Alert
                            message="Error Loading Data"
                            description={error}
                            type="error"
                            showIcon
                            action={
                                <Button size="small" type="primary" onClick={this.fetchDataElements}>
                                    Try Again
                                </Button>
                            }
                        />
                    </div>
                </Card>
            );
        }

        const columns = [
            {
                title: 'Data Element Name',
                dataIndex: 'displayName',
                key: 'displayName',
                width: 300,
                render: (text, dataElement) => {
                    let displayText = text;
                    if (searchValue && searchValue.trim()) {
                        const searchTerm = searchValue.toLowerCase();
                        if (text.toLowerCase().includes(searchTerm)) {
                            const regex = new RegExp(`(${searchValue})`, 'gi');
                            displayText = text.replace(regex, '<mark>$1</mark>');
                        }
                    }

                    return (
                        <div style={{ display: 'flex', alignItems: 'center' }}>
                            <Icon
                                type="database"
                                style={{
                                    color: '#1890ff',
                                    marginRight: '8px'
                                }}
                            />
                            <div>
                                <div
                                    style={{ fontWeight: '500' }}
                                    dangerouslySetInnerHTML={{ __html: displayText }}
                                />
                                {dataElement.shortName && (
                                    <div style={{ fontSize: '12px', color: '#666', marginTop: '2px' }}>
                                        {dataElement.shortName}
                                    </div>
                                )}
                            </div>
                        </div>
                    );
                }
            },
            {
                title: 'Value Type',
                dataIndex: 'valueType',
                key: 'valueType',
                width: 120,
                render: (text) => {
                    const colorMap = {
                        'NUMBER': '#52c41a',
                        'TEXT': '#1890ff',
                        'BOOLEAN': '#fa8c16',
                        'DATE': '#722ed1',
                        'INTEGER': '#13c2c2'
                    };

                    return (
                        <Tag color={colorMap[text] || '#666'} style={{ fontSize: '11px' }}>
                            {text}
                        </Tag>
                    );
                }
            },
            {
                title: 'Domain Type',
                dataIndex: 'domainType',
                key: 'domainType',
                width: 140,
                render: (text) => {
                    const isAggregate = text === 'AGGREGATE';
                    const displayText = isAggregate ? 'Spreadsheets Data' : 'Forms Data';
                    return (
                        <p>
                            {displayText}
                        </p>
                    );
                }
            },
            {
                title: 'Last Updated',
                dataIndex: 'lastUpdated',
                key: 'lastUpdated',
                width: 150,
                render: (text) => (
                    <span style={{ fontSize: '12px', color: '#666' }}>
                        {this.formatDate(text)}
                    </span>
                )
            },
            {
                title: 'Actions',
                key: 'actions',
                width: 120,
                fixed: 'right',
                render: (text, dataElement) => (
                    <Dropdown
                        overlay={this.getDataElementActionsMenu(dataElement)}
                        trigger={['click']}
                        placement="bottomRight"
                    >
                        <Button size="small" icon="more">
                        </Button>
                    </Dropdown>
                )
            }
        ];

        const dataSource = searchValue ? filteredDataElements : dataElements;

        return (
            <div style={{ position: 'relative' }}>
                <Card bodyStyle={{ padding: 0 }}>
                    {/* Header */}
                    <div style={headerStyle}>
                        <div style={{ display: 'flex', alignItems: 'center' }}>
                            <div>
                                <h1 style={{
                                    margin: 0,
                                    fontSize: '24px',
                                    fontWeight: 'bold',
                                }}>
                                    Data Elements
                                </h1>
                                <p style={{ margin: '8px 0 0 0', color: '#666' }}>
                                    Manage and view all data elements in the system
                                </p>
                            </div>
                        </div>
                    </div>

                    {/* Table Content */}
                    <div style={{ padding: '0 24px 24px 24px' }}>
                        {dataElements.length === 0 ? (
                            <div style={{ textAlign: 'center', padding: '60px 0', color: '#999' }}>
                                <Icon type="database" style={{ fontSize: '64px', color: '#d9d9d9', marginBottom: '16px' }} />
                                <div style={{ fontSize: '16px' }}>No data elements found</div>
                            </div>
                        ) : (
                            <div>
                                <div style={{ display: 'flex', alignItems: 'center', marginBottom: 16, gap: 16 }}>
                                    <Search
                                        placeholder="Search data elements by name, ID, code, short name, or description"
                                        value={searchValue}
                                        onChange={(e) => this.handleSearch(e.target.value)}
                                        style={{ width: 500 }}
                                    />
                                    <Button
                                        icon={refreshing ? "loading" : "reload"}
                                        onClick={this.handleRefresh}
                                        disabled={refreshing || isDeleting}
                                        title="Refresh data elements"
                                    >
                                        {refreshing ? 'Refreshing...' : 'Refresh'}
                                    </Button>
                                    {selectedDataElementIds.length > 0 && (
                                        <div style={{ display: 'flex', alignItems: 'center', gap: 8 }}>
                                            <span style={{ color: '#666', fontSize: '14px' }}>
                                                {selectedDataElementIds.length} selected
                                            </span>
                                            <Button
                                                size="small"
                                                onClick={this.handleSelectAll}
                                                disabled={isDeleting || refreshing}
                                            >
                                                Select All
                                            </Button>
                                            <Button
                                                size="small"
                                                onClick={this.handleClearSelection}
                                                disabled={isDeleting || refreshing}
                                            >
                                                Clear
                                            </Button>
                                            <Button
                                                type="danger"
                                                size="small"
                                                icon={isDeleting ? "loading" : "delete"}
                                                onClick={this.handleBulkDelete}
                                                disabled={isDeleting}
                                                loading={isDeleting}
                                            >
                                                {isDeleting ? 'Deleting...' : 'Delete Selected'}
                                            </Button>
                                        </div>
                                    )}
                                </div>
                                {searchValue && (
                                    <div style={{ marginBottom: 16, color: '#666', fontSize: '14px' }}>
                                        <Icon type="search" style={{ marginRight: '4px' }} />
                                        Found {dataSource.length} data element(s) for "{searchValue}"
                                    </div>
                                )}
                                <Table
                                    columns={columns}
                                    dataSource={dataSource}
                                    rowKey="id"
                                    rowSelection={{
                                        selectedRowKeys: selectedDataElementIds,
                                        onChange: this.handleRowSelection,
                                        getCheckboxProps: () => ({
                                            disabled: isDeleting || refreshing,
                                        }),
                                    }}
                                    scroll={{ x: 1200 }}
                                    pagination={{
                                        pageSize: 10,
                                        showSizeChanger: true,
                                        showQuickJumper: true,
                                        showTotal: (total, range) =>
                                            `${range[0]}-${range[1]} of ${total} ${searchValue ? 'filtered' : ''} data elements`,
                                    }}
                                    size="middle"
                                />
                            </div>
                        )}
                    </div>
                </Card>

                {/* Floating Add Button */}
                <div style={{
                    position: 'fixed',
                    bottom: '24px',
                    right: '24px',
                    zIndex: 1000
                }}>
                    <Button
                        type="primary"
                        size="large"
                        shape="circle"
                        icon="plus"
                        onClick={this.handleCreateDataElement}
                        style={{
                            width: '56px',
                            height: '56px',
                            fontSize: '20px',
                            boxShadow: '0 4px 12px rgba(24, 144, 255, 0.3)',
                            border: 'none'
                        }}
                        title="Add New Data Element"
                    />
                </div>
            </div>
        );
    }
}

DataElementsList.contextTypes = {
    d2: PropTypes.object
};

export default DataElementsList;



